        with path.open(encoding="utf-8", errors="replace") as handle:
            for _ in range(8):
                line = handle.readline()
                if not line:
                    break
                title = line.strip().strip("#* _").strip()
                if title.casefold() in {"verified facts", "å·²éªŒè¯äº‹å®?, "å®¡è®¡æ­£æ–‡å¦‚ä¸‹ã€?}:
                    continue
                if title:
                    return " ".join(title.split())[:96]
    except OSError:
